sys_variable_value.value:
(function execute(inputs, outputs) {
    function parseLevel(displayValue) {
        if (!displayValue) {
            return '';
        }
        var parts = displayValue.split(' - ');
        return parts.length > 1 ? parts[1].toUpperCase() : parts[0].toUpperCase();
    }
    function toIsoOrNull(dateField) {
       if (dateField.nil()) {
           return 'null';
        }
    return '"' + dateField.getValue().replace(' ', 'T') + '"';
    }

    outputs.status = inputs.incident.getDisplayValue('state');
    outputs.category = inputs.incident.getDisplayValue('servicedesk_category');
    outputs.subcategory = inputs.incident.getDisplayValue('servicedesk_subcategory');

    outputs.impact = parseLevel(inputs.incident.getDisplayValue('impact'));
    outputs.urgency = parseLevel(inputs.incident.getDisplayValue('urgency'));

    outputs.shortdescription = JSON.stringify(String(inputs.incident.short_description));
    outputs.description = JSON.stringify(String(inputs.incident.description));
    outputs.closecomment = JSON.stringify(String(inputs.incident.close_notes));
    outputs.actualstart = toIsoOrNull(inputs.incident.work_start);
    outputs.actualend = toIsoOrNull(inputs.incident.work_end);
})(inputs, outputs);

